package brainstore

import (
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/entireio/entire-brain/internal/cli/internal/base"
)

const FileLockRetryInterval = 10 * time.Millisecond

var ErrFileLockTimeout = errors.New("file lock timeout")

type FileLock struct {
	path        string
	file        *os.File
	processLock *processFileLock
}

// processFileLocks makes file locks visible to Go goroutines for the full
// AcquireFileLock-to-Close lifetime. The OS lock remains necessary for other
// processes.
var processFileLocks processFileLockRegistry

type processFileLockRegistry struct {
	sync.Mutex
	// os.FileInfo has no portable comparable identity, so lookup uses os.SameFile.
	locks []*processFileLock
}

type processFileLock struct {
	parent   os.FileInfo
	basename string
	token    chan struct{}
	refs     int // holders and waiters; protected by processFileLocks
}

func AcquireFileLock(path, code string, timeout time.Duration) (*FileLock, error) {
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return nil, fmt.Errorf("create lock directory: %w", err)
	}
	parent, basename, err := fileLockIdentity(path)
	if err != nil {
		return nil, err
	}
	deadline := time.Now().Add(timeout)
	processLock, ok := acquireProcessFileLock(parent, basename, deadline, timeout)
	if !ok {
		return nil, fileLockTimeoutError(code, path)
	}
	defer func() {
		if processLock != nil {
			processLock.release()
		}
	}()

	for {
		if err := base.RejectUnsafeExistingRegularFile(path, "lock file"); err != nil {
			return nil, err
		}
		f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR|base.FileLockOpenFlags(), 0o600)
		if err != nil {
			return nil, fmt.Errorf("open lock file: %w", err)
		}
		if err := base.RejectOpenFileAlias(path, f, "lock file"); err != nil {
			_ = f.Close()
			return nil, err
		}
		err = tryLockFile(f)
		if err == nil {
			WriteLockOwnerMetadata(path)
			lock := &FileLock{path: path, file: f, processLock: processLock}
			processLock = nil
			return lock, nil
		}
		_ = f.Close()
		if !isLockBusy(err) {
			return nil, fmt.Errorf("lock file: %w", err)
		}
		if timeout <= 0 || time.Now().Add(FileLockRetryInterval).After(deadline) {
			return nil, fileLockTimeoutError(code, path)
		}
		time.Sleep(FileLockRetryInterval)
	}
}

func fileLockIdentity(path string) (os.FileInfo, string, error) {
	parent, err := os.Stat(filepath.Dir(path))
	if err != nil {
		return nil, "", fmt.Errorf("stat lock directory: %w", err)
	}
	if !parent.IsDir() {
		return nil, "", fmt.Errorf("lock directory must be a directory: %s", filepath.Dir(path))
	}
	return parent, filepath.Base(path), nil
}

func acquireProcessFileLock(parent os.FileInfo, basename string, deadline time.Time, timeout time.Duration) (*processFileLock, bool) {
	processFileLocks.Lock()
	lock := processFileLocks.find(parent, basename)
	if lock == nil {
		lock = &processFileLock{parent: parent, basename: basename, token: make(chan struct{}, 1)}
		processFileLocks.locks = append(processFileLocks.locks, lock)
	}
	lock.refs++
	processFileLocks.Unlock()

	select {
	case lock.token <- struct{}{}:
		return lock, true
	default:
	}
	if timeout <= 0 {
		lock.releaseReference()
		return nil, false
	}
	remaining := time.Until(deadline)
	if remaining <= 0 {
		lock.releaseReference()
		return nil, false
	}
	timer := time.NewTimer(remaining)
	defer timer.Stop()
	select {
	case lock.token <- struct{}{}:
		return lock, true
	case <-timer.C:
		lock.releaseReference()
		return nil, false
	}
}

func (l *processFileLock) release() {
	<-l.token
	l.releaseReference()
}

func (r *processFileLockRegistry) find(parent os.FileInfo, basename string) *processFileLock {
	for _, lock := range r.locks {
		if lock.basename == basename && os.SameFile(lock.parent, parent) {
			return lock
		}
	}
	return nil
}

func (l *processFileLock) releaseReference() {
	processFileLocks.Lock()
	defer processFileLocks.Unlock()
	l.refs--
	if l.refs != 0 {
		return
	}
	for i, lock := range processFileLocks.locks {
		if lock == l {
			copy(processFileLocks.locks[i:], processFileLocks.locks[i+1:])
			last := len(processFileLocks.locks) - 1
			processFileLocks.locks[last] = nil
			processFileLocks.locks = processFileLocks.locks[:last]
			return
		}
	}
}

func fileLockTimeoutError(code, path string) error {
	// The holder named below is ALIVE: these are flock/LockFileEx locks, which
	// the kernel releases the moment their process exits, so a timeout can
	// never be a stale lockfile. That is what licenses naming an action here.
	return fmt.Errorf("%s: timed out acquiring lock at %s%s: %w — another entire-brain operation is still running; wait for it to finish or stop that process, then retry", code, path, describeFileLockHolder(path), ErrFileLockTimeout)
}

// fileLockMetadataMaxBytes bounds the read of an owner file.
// WriteLockOwnerMetadata writes two short lines; anything larger is not ours
// and is ignored.
const fileLockMetadataMaxBytes = 512

// FileLockOwnerSuffix names the sidecar carrying a lock's owner metadata.
//
// The metadata lives BESIDE the lock rather than inside it because Windows
// byte-range locks are MANDATORY. tryLockFile takes an exclusive LockFileEx
// over byte 0, and a read overlapping a locked range fails with
// ERROR_LOCK_VIOLATION — so metadata stored at offset 0 of the lock file is
// unreadable by any other process exactly when a holder exists, which is the
// only moment it is worth reading. POSIX flock is advisory and hides this
// completely: the same code read the metadata fine on Linux and macOS and came
// back empty-handed on Windows shard 3.
//
// Storing it at a non-zero offset inside the lock file would also work today,
// but that ties this diagnostic to the exact byte range tryLockFile happens to
// lock, so a later change there would silently break the message on Windows
// alone. A separate file nothing ever locks is the version that cannot rot.
const FileLockOwnerSuffix = ".owner"

// describeFileLockHolder turns the metadata WriteLockOwnerMetadata stores
// beside every lock into the one fact a blocked caller actually needs: WHICH
// process is holding this lock, and for how long.
//
// The pid and timestamp have been written on every acquisition since the lock
// package existed and were read by nothing, so a contended brain produced
// "brain_locked: timed out acquiring lock at .../locks/write.lock" and stopped
// there — naming the file the user already knew about and withholding the only
// thing that identifies the culprit. On a machine running a background watcher,
// a detached backfill, a watch loop and a terminal, that is the difference
// between a diagnosable stall and a mystery.
//
// It is advisory and fails silently to the empty string: the message must never
// be worse than the one it replaces. A pid whose process is gone is NOT
// reported — the OS releases the lock when its holder dies, so stale metadata
// names an innocent bystander, and naming one would be worse than naming
// nobody.
//
// The sidecar is written by the holder immediately after it wins the lock, so
// the lock itself serializes the writers and there is exactly one. It is read
// only on a TIMEOUT, which is proof somebody holds the lock right now, so the
// name it gives is the current holder — except in the instant between another
// process acquiring and stamping its own name, where it is the one just before.
// Either way it names a process that was holding this lock, which is what the
// message claims. It is never treated as proof a holder is alive: the lock
// remains the only authority on that.
func describeFileLockHolder(lockPath string) string {
	path := lockPath + FileLockOwnerSuffix
	// Lstat first, and demand a plain file. O_NOFOLLOW rejects a symlink but
	// NOT a fifo, and opening a fifo for reading blocks until someone opens the
	// write end -- which would hang the very error path whose whole job is to
	// report that we already waited long enough.
	info, err := os.Lstat(path)
	if err != nil || !info.Mode().IsRegular() {
		return ""
	}
	f, err := os.OpenFile(path, os.O_RDONLY|base.FileLockOpenFlags(), 0)
	if err != nil {
		return ""
	}
	defer func() { _ = f.Close() }()
	// Re-check through the descriptor: the path could have been swapped between
	// the Lstat and the open.
	if opened, statErr := f.Stat(); statErr != nil || !opened.Mode().IsRegular() {
		return ""
	}
	buf := make([]byte, fileLockMetadataMaxBytes)
	n, err := f.Read(buf)
	if n <= 0 || (err != nil && !errors.Is(err, io.EOF)) {
		return ""
	}
	pid := 0
	var since time.Time
	for _, line := range strings.Split(string(buf[:n]), "\n") {
		key, value, ok := strings.Cut(strings.TrimSpace(line), "=")
		if !ok {
			continue
		}
		switch key {
		case "pid":
			parsed, convErr := strconv.Atoi(value)
			if convErr == nil {
				pid = parsed
			}
		case "created_at":
			if parsed, convErr := time.Parse(time.RFC3339Nano, value); convErr == nil {
				since = parsed
			}
		}
	}
	if pid <= 0 || !ProcessAlive(pid) {
		return ""
	}
	// A holder that is US is the most valuable answer of all: it means this
	// process is blocked on a lock it already holds, which no amount of waiting
	// will resolve. Naming it as self stops the reader hunting for another
	// process.
	who := fmt.Sprintf("pid %d", pid)
	if pid == os.Getpid() {
		who = fmt.Sprintf("this process, pid %d", pid)
	}
	if since.IsZero() {
		return fmt.Sprintf(" (held by %s)", who)
	}
	held := time.Since(since)
	if held < 0 {
		held = 0
	}
	return fmt.Sprintf(" (held by %s for %s)", who, held.Round(time.Second))
}

// WriteLockOwnerMetadata records who holds lockPath, in the sidecar beside it.
// Called by the winner immediately after the lock is taken, so the lock itself
// guarantees a single writer.
//
// Best-effort throughout: a lock must never fail to be acquired because its
// diagnostic could not be written. There is deliberately no fsync — the point
// is for another PROCESS to read this within seconds, which the page cache
// already provides, and crash durability is worthless for a file whose whole
// subject is a process that no longer exists.
func WriteLockOwnerMetadata(lockPath string) {
	path := lockPath + FileLockOwnerSuffix
	if err := base.RejectUnsafeExistingRegularFile(path, "lock owner file"); err != nil {
		return
	}
	f, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_TRUNC|base.FileLockOpenFlags(), 0o600)
	if err != nil {
		return
	}
	defer func() { _ = f.Close() }()
	_, _ = fmt.Fprintf(f, "pid=%d\ncreated_at=%s\n", os.Getpid(), time.Now().UTC().Format(time.RFC3339Nano))
}

func (l *FileLock) Close() error {
	if l == nil || l.file == nil {
		return nil
	}
	unlockErr := unlockFile(l.file)
	closeErr := l.file.Close()
	l.file = nil
	if l.processLock != nil {
		l.processLock.release()
		l.processLock = nil
	}
	if unlockErr != nil {
		return unlockErr
	}
	return closeErr
}
# Filesystem safety

Containment boundaries, symlink policy, and the rationale behind the shared filesystem anchors. Read before changing filesystem access or its exceptions.

Repository paths in code spans are relative to the repository root unless stated otherwise.

### `.entire` Must Be a Directory

`<worktree-root>/.entire` is either absent or a real directory. A regular file, a
symlink — **including a symlink pointing at a perfectly good directory** — a
FIFO, a socket, or a device is a broken repo, and a command that would read or
write through the path stops instead.

**The entries directly inside it must be regular files or directories.** That is
an allowlist, not a list of known-bad types: Entire only ever creates files and
directories under `.entire`, so anything else arrived some other way and a mode
bit nobody has considered yet is refused by default. A symlinked
`.entire/metadata` redirects transcripts; a symlinked `.entire/settings.local.json`
redirects the file that names the command Entire executes at pre-push; a FIFO in
either place hangs the read instead. The scan is one level deep, and
`fs.ModeIrregular` is its one deliberate exception — see the entry-scan
mechanics below.

`paths.ValidateEntireDirAt(worktreeRoot)` / `paths.RequireEntireDir(ctx)`
(`paths/entiredir.go`) are the only implementation. The stat is `Lstat`, not
`Stat`, which is the whole point: `.entire` holds session metadata, transcripts,
and the redaction settings that decide what may be committed, so a path someone
else owns the far end of is not one we write through. Absent is fine (Entire is
not enabled yet, or `enable` is about to create it). A stat error other than
"not exist" is a failure — it is not evidence the invariant is violated, but it
is not evidence it holds either, and the caller's next move is to write there.
Not memoized, deliberately: the `Lstat` and the one-level listing are free next
to the…634 tokens truncated…n a leak would fail closed). Adding an `Lstat` here
reintroduces that race, which matters because `.entire/tmp` and
`.entire/metadata/<session>` churn under concurrent hooks. The entries are
checked **before** `ReadDir`'s error, because `os.ReadDir` returns what it
managed to read alongside a partial-read error and an unsupported entry among
those is a positive finding — a stronger statement than "the listing failed". One
error names the first offender in `ReadDir`'s sorted order (so the message is
deterministic) and counts the rest, rather than one error per entry: the remedy
is identical for all of them, and a user who reruns the command once per planted
entry is paying for our formatting.

**`fs.ModeIrregular` is tolerated, and that is the one place the allowlist
bends.** Windows overloads the bit: Go maps every reparse tag it has no category
for onto it (the `default` arm of `fileStat.mode` in `os/types_windows.go`),
which lands NTFS directory junctions *and* OneDrive Files On-Demand placeholders
in the same bucket, indistinguishable from a `DirEntry`. Refusing the bucket
would hard-fail every command in a repo inside a synced folder, with a remedy the
user cannot act on, and the placeholder arrives with nobody attacking anything.
The junction it would also catch cannot arrive by checkout — git has no
tree-object mode for one — so planting it already requires local code execution,
at which point this check is not what stands in the way. **The bit is masked
out of the type, not matched against it** — `mode.Type() &^ fs.ModeIrregular`
must equal `0` or `fs.ModeDir` — because Windows does not hand it over alone:
`ModeDir` is withheld only for a *name-surrogate* reparse tag, and the cloud
tags are not surrogates, so a placeholder **directory** arrives as
`ModeDir|ModeIrregular` while a junction (a surrogate) arrives as
`ModeIrregular` by itself. `.entire`'s own entries are mostly directories, so an
exact match on the bare bit would reject `metadata`, `logs`, and `tmp` in exactly
the synced folder the tolerance exists for. Masking does not soften the rest of
the field: anything carrying a rejected type is rejected whatever else it
carries, `ModeIrregular` included.

**The comparison is against the whole type field, never `IsRegular`/`IsDir`.**
Those examine single bits (`IsDir` is `mode&ModeDir != 0`), so an allowlist
keyed on them lets a rejected type in by *also* setting an accepted bit:
`ModeDir|ModeSymlink` and `ModeDir|ModeNamedPipe` both satisfy `IsDir`, and so
does the all-bits-set unknown mode above — which is what made the "even a leak
would fail closed" claim false until it was fixed. An allowlist a rejected type
can enter by setting an extra bit is not an allowlist.
`TestUnsupportedEntryType` pins each combination. Distinguishing junction from
placeholder would mean reading the reparse tag through a
Windows-only syscall (`FindFirstFile`, then `Reserved0 & 0x20000000` for the
name-surrogate tags); that is the upgrade path if junctions ever become worth
catching.

**A settings file is never read through a link, and the settings reader enforces
that itself.** `readConfined` (`settings/settings.go`) — the chokepoint every
settings read funnels through, including `LoadFromFile`, `LoadProjectRaw`,
`LoadLocalRaw`, and clone preferences — `Lstat`s the entry through its own
`os.Root` handle and refuses a symlink outright, wrapping
`paths.ErrEntireDirUnsupportedEntry` via the shared `paths.SymlinkedEntryError`
(the symlink-specific message builder, which names the link target; the entry
scan reaches it through `unsupportedEntryError` and describes other types with
`describeMode`).

This is deliberately redundant with the `.entire` entry scan, because the two
cover different callers: the scan hangs off the root pre-run and
`LoadEntireSettings`, while **more than twenty files call `settings.Load`
directly** — `strategy/hooks.go`, `manual_commit_hooks.go`,
`checkpoint/remote/*`, `review/*` — and reach settings without ever passing the
pre-run.

**`os.Root` confinement is not the invariant, and was not sufficient.** Measured
against `readConfined` before the change: an absolute target (even one pointing
inside `.entire`) and an escaping relative target were refused, but as `path
escapes from parent`, naming neither cause nor fix; and two shapes got through:

| link | before | after |
| --- | --- | --- |
| `settings.local.json -> planted.json` (relative, stays inside) | **followed** | refused |
| `settings.json -> missing.json` (dangling) | **ENOENT → silently default settings** | refused |

The dangling case was the worse of the two: every caller reads ENOENT as
"absent", so a planted link made Entire ignore the project's settings without
saying anything. Do not "simplify" the `Lstat` away on the grounds that
`os.OpenRoot` already confines the read — it confines it, which is a different
property from refusing a link.
# Entire repository agent guide — Graph and Brain

Use Brain for task context, retained knowledge, and history.
ALWAYS check Brain availability and version once per session, at the first
substantive task or historical question, BEFORE the brief or any fallback:

    entire brain version
    entire brain capabilities --json

Validate the version output and structured capability report, not just the exit
status. Confirm the required features are supported; use command help when the
report does not identify a required command. Record the version, supported
capabilities, and an available, missing, or unsupported result for the session.
A dev version is not evidence of an outdated binary; check its capabilities.
EVERY tool-unavailability fallback MUST trace to this recorded check and be
explained to the user. Capabilities do not prove repository readiness: record
later query failures or missing-index evidence separately, and limit each
fallback to the affected question. Never defer the preflight until a query fails.

ALWAYS begin a substantive task with:

    entire brain brief "<task>" --json

Run the brief before substantive source exploration or implementation.
Familiarity with the repository, supplied file paths, and remembered context
do not waive this requirement. Specs, reviews, and refactoring plans count
as substantive tasks.

Previous decisions, rationale, prior attempts, documentation, durable project
memories, and earlier sessions MUST be investigated with Brain first, ALWAYS.
Knowing what the current code does does not establish why it was written.
Do not substitute recollection, source comments, or a plausible explanation
for retrieval of the recorded evidence.

Retrieve prior decisions, rejected approaches and rationale with recall, not
with query and not from the brief's memories sample alone:

    entire brain recall "<question>" --json

Memories are the default retrieval surface. The brief's precedent section lists
each surfaced memory's source sessions (session, transcript, commit,
checkpoint); follow those anchors when you need the detail behind a memory.
The brief does not search transcript history. Search transcripts only as an
explicit escalation, when memories and their anchors miss:

    entire brain query --source history "<question>" --json

Use Brain retrieval for recorded knowledge. Use entities history when connecting
code changes to earlier checkpoints or sessions. ALWAYS retrieve relevant prior
decisions and attempts before proposing to replace an existing approach.
ALWAYS consult relevant retained knowledge when reviewing a change.
A general brief does not replace targeted retrieval for a historical question
that the brief did not answer.

Cite the retrieved evidence for historical claims. Distinguish recorded rationale
from inference. An empty result means no evidence was found; it does not establish
that a decision or previous attempt never existed.

Durable memories are Brain's episodic record. When you establish something durable
that the code does not already state - a decision and its rationale, an
invariant, a gotcha that cost you time - RECORD it before finishing:

    entire brain remember "<memory>" --path <category.subcategory.type> --json

Categories are architecture, constraints, preferences, project and workflow.
Each path segment uses only lowercase letters, digits and underscores: write
project.ci_cache.layout, not project.ci-cache.layout.
Omitting --path classifies the memory for you and requires a supported coding
agent on PATH; pass --path when none is guaranteed. Retrieve with recall and
re-check anchors with verify. A memory you author has no source anchor, so verify
reports it unverifiable-here - that is expected, not a failure.

Brain semantic answers refer to a stored index, which may differ from current
working-tree source. Verify claims about present behavior against current source
and executed tests.

Use Graph for code discovery, structural understanding, and semantic change analysis.
ALWAYS check Graph availability and version once per session, at the first
structural question or code discovery task, BEFORE querying or using a fallback:

    entire graph version --json
    entire graph capabilities --json

Validate the output, not just the exit status: version must identify the
entire-graph provider, and capabilities must report the features and semantic
coverage needed for the question. Use command help to verify required commands
when the capability report does not identify them. Record the version, supported
capabilities, and an available, missing, or unsupported result for the session.
A dev version is not evidence of an outdated binary; check its capabilities.
EVERY tool-unavailability fallback MUST trace to this recorded check and be
explained to the user. A later query failure or coverage gap must be recorded
separately and only permits a fallback for the affected question. Never skip the
preflight because a file is known or a grep looks easier.

Start needed code discovery with:

    entire graph query --repo . --profile full --head --format agent --max-context-bytes 4096 --query "<task>"

Code relationships — callers, callees, dependents, implementors, type consumers,
routes, and blast radius — MUST be answered with Graph first, ALWAYS, even when
the task names the exact file or you have already read the implementation.
Use neighbors for a specific relationship and impact for blast radius.
Grep may supplement a Graph answer; it NEVER replaces the required Graph query.

ALWAYS run impact before editing exported code or shared-library symbols.
Writing a spec, scoping a refactor, reviewing a proposed change, and challenging
a design count as editing for this rule. Cover every affected exported or
shared-library symbol and cite its impact result. Do not infer that a change
is local merely because its implementation occupies one file.

Use Graph diff, commit, or checkpoint for entity-level revision comparisons.
Read the textual diff as needed to inspect the implementation.

Text occurrences the graph does not model — environment-variable names,
configuration values, string keys, and package-manifest entries — belong in
text search. One legitimate text search does not authorize using grep to answer
a relationship question.

ALWAYS use --head for interactive Graph queries by default, including the first
query. Use the working tree ONLY when the answer depends on uncommitted edits;
then omit --head. Working-tree queries rebuild the snapshot on every call and
never cache; --head permits reuse of the committed-tree cache. Never present
committed-tree results as analysis of edits they do not contain.
Before several --head queries, prewarm the matching cache variant.
Ask per-symbol commands before bulk streams. Never dump unfiltered whole-repo
NDJSON into context; redirect it to a file and extract the needed records.

An empty Graph result is NEVER proof of no consumers. Check completeness,
resolution, and confidence. Verify heuristic relationships in focused source.
For dependency injection, inspect type consumers as well as CALLS. Check
dynamic dispatch and unmodeled relationships with targeted supplementary
inspection. State unresolved coverage limits in the answer.

Both sets of mandatory rules apply.
Brain answers recorded-context and historical questions; Graph answers structural
questions and entity-level revision comparisons.

Locations supplied by Brain may replace a Graph location query ONLY.
They NEVER replace required neighbors or impact analysis.
Graph results NEVER replace required retrieval of prior decisions or attempts.
When a task involves both relationships and history, query both tools.

Choose tools by question class, not convenience.
Knowing a file or symbol's location permits direct source inspection for that
location; it NEVER exempts relationship questions from Graph or historical
questions from Brain. Small edits, follow-ups, read-only reconnaissance, specs,
and reviews are subject to the same rules for the enabled products.
Do not re-read files or retrieved records merely to repeat an answer from the same
unchanged source view.
A follow-up read MUST address a specific missing fact, stale result, heuristic
relationship, or source the payload did not carry. A [complete] result already supplies
its displayed body for the observed source view; the marker does not remove the need
to check a stale result or required source outside that body. Repeating
an answered question in source is not verification.
Inspect the source Graph displays at useful locations before editing. A result marked [complete]
