	if err != nil {
		return fmt.Errorf("%s: create pinned corpus publication leaf: %w", brainstore.StateUnsafeCode, err)
	}
	removeTemp := true
	defer func() {
		_ = temp.Close()
		if removeTemp {
			_ = pinned.patternsRoot.Remove(tempName)
		}
	}()
	hash := sha256.New()
	copied, copyErr := io.Copy(io.MultiWriter(temp, hash), io.LimitReader(staging, brainsto…199 tokens truncated…, createErr := os.OpenFile(destination, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
		if createErr != nil {
			cleanup()
			return "", nil, fmt.Errorf("%s: create SQLite verification snapshot: %w", StateCorruptCode, createErr)
		}
		remaining := PrivacySQLiteSnapshotMaxBytes - totalCopied
		copied, copyErr := io.Copy(snapshot, io.LimitReader(source.file, remaining+1))
		closeErr := snapshot.Close()
		if copyErr != nil || closeErr != nil || copied != source.expected.Size() || copied > remaining {
			cleanup()
			return "", nil, fmt.Errorf("%s: SQLite store or WAL changed or exceeded bounds while snapshotting", StateUnsafeCode)
		}
		totalCopied += copied
	}

