package cli

import (
 "bytes"
 "context"
 "crypto/rand"
 "crypto/sha256"
 "database/sql"
 "encoding/hex"
 "encoding/json"
 "errors"
 "fmt"
 "io"
 "os"
 "path/filepath"
 "sort"
 "strings"
 "time"

 "github.com/entireio/entire-brain/internal/cli/internal/base"
 "github.com/entireio/entire-brain/internal/cli/internal/brainstore"
 "github.com/entireio/entire-brain/internal/cli/internal/sqlitedriver"
)

const (
 factIndexSchemaVersion = 1
 factIndexTokenizerVersion = 1
 factIndexLocusVersion = 1
 factIndexScorerVersion = 1
 factIndexMaxBytes int64 = 64 << 20
 factIndexMaxDocuments = 100000
 factIndexDescriptorMaxBytes int64 = 4096
 factIndexMaxDirectoryEntries = 32
 factIndexNamespace = "fact-lexical-v1"
 factIndexLockName = "write.lock"
 factIndexPublishPrefix = ".publish-"
)

var (
 errFactIndexUnsafe = errors.New("unsafe fact index cache")
 errFactIndexBudget = errors.New("fact index cache budget exceeded")
)

type factIndexDocument struct {
 Signature string
 Length int
 // Even nil is the computed effective locus. Readers never derive it again.
 Locus []string
}

type factIndexPosting struct { Document int; Frequency int }

type factPreparedIndex struct {
 docs []factIndexDocument
 reused bool
 db *sql.DB
 privateDir string
 generation string
}

type factIndexRevision struct {
 Schema int `json:"schema"`
 Tokenizer int `json:"tokenizer"`
 Locus int `json:"locus"`
 Scorer int `json:"scorer"`
}

type factIndexDescriptor struct {
 Revision factIndexRevision `json:"revision"`
 Source string `json:"source"`
 Documents int `json:"documents"`
 Size int64 `json:"size"`
 SHA256 string `json:"sha256"`
 CreatedAt time.Time `json:"created_at"`
}

func currentFactIndexRevision() factIndexRevision {
 return factIndexRevision{factIndexSchemaVersion,factIndexTokenizerVersion,factIndexLocusVersion,factIndexScorerVersion}
}

func factIndexRecordSignature(record factRecord) (string,error) {
 data,err:=json.Marshal(record);if err!=nil{return "",fmt.Errorf("encode fact index record: %w",err)}
 sum:=sha256.Sum256(data);return hex.EncodeToString(sum[:]),nil
}

func factIndexSourceRevision(ctx context.Context,scope string,source []factRecord)(string,[]string,error){
 if len(source)>factIndexMaxDocuments{return "",nil,errFactIndexBudget}
 h:=sha256.New()
 header:=struct{Revision factIndexRevision;Scope string;Projection string}{currentFactIndexRevision(),scope,"factstore-effective-record-v3"}
 if err:=json.NewEncoder(h).Encode(header);err!=nil{return "",nil,fmt.Errorf("encode fact index revision: %w",err)}
 signatures:=make([]string,len(source))
 for i:=range source {
  if err:=ctx.Err();err!=nil{return "",nil,err}
  data,err:=json.Marshal(source[i]);if err!=nil{return "",nil,fmt.Errorf("encode fact index source: %w",err)}
  sum:=sha256.Sum256(data);signatures[i]=hex.EncodeToString(sum[:])
  _,_=h.Write(data);_,_=h.Write([]byte{'\n'})
 }
 return hex.EncodeToString(h.Sum(nil)),signatures,nil
}

func factIndexDirectory(env base.EntireEnv,scope string)(string,error){
 if strings.TrimSpace(scope)==""{return "",fmt.Errorf("fact index requires a source identity")}
 dirs,err:=base.ResolvePluginDirs(env);if err!=nil{return "",err}
 sum:=sha256.Sum256([]byte(scope))
 return filepath.Join(dirs.Cache,factIndexNamespace,hex.EncodeToString(sum[:])),nil
}

// The cache root is resolved by PluginDirs, not derived from an artifact path.
// All descendants are pinned and refuse links before any reads or mutations.
type factIndexPinnedDirectory struct {
 cachePath string
 cache *os.Root
 cacheInfo os.FileInfo
 namespace *os.Root
 namespaceInfo os.FileInfo
 scope *os.Root
 scopeInfo os.FileInfo
 scopeName string
}

func factIndexOpenDirectoryPath(path string)(*os.Root,os.FileInfo,error){
 info,err:=os.Lstat(path)
 if os.IsNotExist(err){
  parentPath:=filepath.Dir(path)
  if parentPath==path{return nil,nil,err}
  parent,_,openErr:=factIndexOpenDirectoryPath(parentPath);if openErr!=nil{return nil,nil,openErr}
  defer parent.Close()
  name:=filepath.Base(path)
  if mkdirErr:=parent.Mkdir(name,0700);mkdirErr!=nil&&!os.IsExist(mkdirErr){return nil,nil,mkdirErr}
  return factIndexOpenChild(parent,name)
 }
 if err!=nil{return nil,nil,err}
 if info.Mode()&os.ModeSymlink!=0||!info.IsDir(){return nil,nil,fmt.Errorf("%w: cache root is not a directory",errFactIndexUnsafe)}
 root,err:=os.OpenRoot(path);if err!=nil{return nil,nil,err}
 opened,err:=root.Stat(".")
 if err!=nil||!os.SameFile(info,opened){_=root.Close();return nil,nil,fmt.Errorf("%w: cache root changed while opening",errFactIndexUnsafe)}
 return root,info,nil
}

func factIndexOpenChild(parent *os.Root,name string)(*os.Root,os.FileInfo,error){
 info,err:=parent.Lstat(name);if err!=nil{return nil,nil,err}
 if info.Mode()&os.ModeSymlink!=0||!info.IsDir(){return nil,nil,fmt.Errorf("%w: cache component is not a directory",errFactIndexUnsafe)}
 child,err:=parent.OpenRoot(name);if err!=nil{return nil,nil,err}
 opened,err:=child.Stat(".");current,currentErr:=parent.Lstat(name)
 if err!=nil||currentErr!=nil||current.Mode()&os.ModeSymlink!=0||!os.SameFile(info,opened)||!os.SameFile(info,current){
  _=child.Close();return nil,nil,fmt.Errorf("%w: cache component changed while opening",errFactIndexUnsafe)
 }
 return child,info,nil
}

func openFactIndexPinnedDirectory(env base.EntireEnv,scope string)(*factIndexPinnedDirectory,error){
 dirs,err:=base.ResolvePluginDirs(env);if err!=nil{return nil,err}
 path,err:=factIndexDirectory(env,scope);if err!=nil{return nil,err}
 pinned:=&factIndexPinnedDirectory{cachePath:dirs.Cache,scopeName:filepath.Base(path)}
 pinned.cache,pinned.cacheInfo,err=factIndexOpenDirectoryPath(dirs.Cache);if err!=nil{return nil,err}
 fail:=func(e error)(*factIndexPinnedDirectory,error){pinned.Close();return nil,e}
 if err=pinned.cache.Mkdir(factIndexNamespace,0700);err!=nil&&!os.IsExist(err){return fail(err)}
 pinned.namespace,pinned.namespaceInfo,err=factIndexOpenChild(pinned.cache,factIndexNamespace);if err!=nil{return fail(err)}
 if err=pinned.namespace.Mkdir(pinned.scopeName,0700);err!=nil&&!os.IsExist(err){return fail(err)}
 pinned.scope,pinned.scopeInfo,err=factIndexOpenChild(pinned.namespace,pinned.scopeName);if err!=nil{return fail(err)}
 if err=pinned.validate();err!=nil{return fail(err)}
 return pinned,nil
}

func (p *factIndexPinnedDirectory) Close(){
 if p==nil{return};if p.scope!=nil{_=p.scope.Close()};if p.namespace!=nil{_=p.namespace.Close()};if p.cache!=nil{_=p.cache.Close()}
}

func (p *factIndexPinnedDirectory) validate()error{
 current,err:=os.Lstat(p.cachePath)
 if err!=nil||current.Mode()&os.ModeSymlink!=0||!os.SameFile(p.cacheInfo,current){return fmt.Errorf("%w: cache root changed",errFactIndexUnsafe)}
 for _,entry:=range []struct{parent,child *os.Root;name string;info os.FileInfo}{{p.cache,p.namespace,factIndexNamespace,p.namespaceInfo},{p.namespace,p.scope,p.scopeName,p.scopeInfo}}{
  current,e:=entry.parent.Lstat(entry.name);opened,openErr:=entry.child.Stat(".")
  if e!=nil||openErr!=nil||current.Mode()&os.ModeSymlink!=0||!os.SameFile(entry.info,current)||!os.SameFile(entry.info,opened){return fmt.Errorf("%w: pinned cache directory changed",errFactIndexUnsafe)}
 }
 return nil
}

func factIndexOpenLeaf(root *os.Root,name string,max int64)(*os.File,os.FileInfo,error){
 info,err:=root.Lstat(name);if err!=nil{return nil,nil,err}
 if info.Mode()&os.ModeSymlink!=0||!info.Mode().IsRegular(){return nil,nil,fmt.Errorf("%w: cache leaf is not a regular file",errFactIndexUnsafe)}
 if info.Size()<1||info.Size()>max{return nil,nil,errFactIndexBudget}
 f,err:=root.OpenFile(name,os.O_RDONLY|base.FileLockOpenFlags()|base.MemoryStateReadOpenFlags(),0);if err!=nil{return nil,nil,err}
 opened,err:=f.Stat();current,currentErr:=root.Lstat(name)
 if err!=nil||currentErr!=nil||current.Mode()&os.ModeSymlink!=0||!os.SameFile(info,opened)||!os.SameFile(info,current){_=f.Close();return nil,nil,fmt.Errorf("%w: cache leaf changed while opening",errFactIndexUnsafe)}
 if err=base.RejectOpenFileHardlink(name,f,opened,"fact index");err!=nil{_=f.Close();return nil,nil,fmt.Errorf("%w: %w",errFactIndexUnsafe,err)}
 return f,info,nil
}

func factIndexLeafUnchanged(root *os.Root,name string,f *os.File,info os.FileInfo)error{
 opened,err:=f.Stat();current,currentErr:=root.Lstat(name)
 if err!=nil||currentErr!=nil||current.Mode()&os.ModeSymlink!=0||!os.SameFile(info,opened)||!os.SameFile(info,current)||opened.Size()!=info.Size()||current.Size()!=info.Size()||!opened.ModTime().Equal(info.ModTime())||!current.ModTime().Equal(info.ModTime()){
  return fmt.Errorf("%w: cache leaf changed during reading",errFactIndexUnsafe)
 }
 return nil
}

func readFactIndexDescriptor(ctx context.Context,p *factIndexPinnedDirectory,digest string)(factIndexDescriptor,error){
 var descriptor factIndexDescriptor
 name:=digest+".json";f,info,err:=factIndexOpenLeaf(p.scope,name,factIndexDescriptorMaxBytes);if err!=nil{return descriptor,err};defer f.Close()
 data,err:=io.ReadAll(io.LimitReader(&factIndexContextReader{ctx:ctx,reader:f},factIndexDescriptorMaxBytes+1));if err!=nil{return descriptor,err}
 if int64(len(data))>factIndexDescriptorMaxBytes{return descriptor,errFactIndexBudget}
 if err=factIndexLeafUnchanged(p.scope,name,f,info);err!=nil{return descriptor,err}
 decoder:=json.NewDecoder(bytes.NewReader(data));decoder.DisallowUnknownFields()
 if err=decoder.Decode(&descriptor);err!=nil{return descriptor,fmt.Errorf("decode fact index descriptor: %w",err)}
 var extra any;if err=decoder.Decode(&extra);!errors.Is(err,io.EOF){return descriptor,fmt.Errorf("invalid trailing fact index descriptor data")}
 if descriptor.Revision!=currentFactIndexRevision()||descriptor.Source!=digest||!factIndexHexDigest(descriptor.SHA256)||descriptor.Size<1||descriptor.Size>factIndexMaxBytes||descriptor.Documents<0||descriptor.Documents>factIndexMaxDocuments{return descriptor,fmt.Errorf("invalid fact index descriptor")}
 return descriptor,p.validate()
}

type factIndexContextReader struct {ctx context.Context;reader io.Reader}
func (r *factIndexContextReader) Read(data []byte)(int,error){if err:=r.ctx.Err();err!=nil{return 0,err};return r.reader.Read(data)}

func factIndexHexDigest(value string)bool{
 if len(value)!=sha256.Size*2{return false};_,err:=hex.DecodeString(value);return err==nil&&strings.ToLower(value)==value
}

// Only this descriptor-bound private snapshot is ever passed to SQLite. The
// byte digest covers postings and computed loci, not merely database metadata.
func snapshotFactIndex(ctx context.Context,p *factIndexPinnedDirectory,descriptor factIndexDescriptor)(string,string,error){
 name:=descriptor.Source+".sqlite";source,info,err:=factIndexOpenLeaf(p.scope,name,factIndexMaxBytes);if err!=nil{return "","",err};defer source.Close()
 if info.Size()!=descriptor.Size{return "","",fmt.Errorf("fact index database size changed")}
 privateDir,err:=os.MkdirTemp("","entire-brain-fact-index-read-");if err!=nil{return "","",err}
 success:=false;defer func(){if !success{_=os.RemoveAll(privateDir)}}()
 path:=filepath.Join(privateDir,"index.sqlite")
 target,err:=os.OpenFile(path,os.O_WRONLY|os.O_CREATE|os.O_EXCL,0600);if err!=nil{return "","",err}
 h:=sha256.New();copied,copyErr:=io.CopyBuffer(io.MultiWriter(target,h),io.LimitReader(&factIndexContextReader{ctx:ctx,reader:source},factIndexMaxBytes+1),make([]byte,64<<10));closeErr:=target.Close()
 if copyErr!=nil{return "","",copyErr};if closeErr!=nil{return "","",closeErr}
 if copied!=descriptor.Size||copied>factIndexMaxBytes||hex.EncodeToString(h.Sum(nil))!=descriptor.SHA256{return "","",fmt.Errorf("fact index database failed its committed digest")}
 if err=factIndexLeafUnchanged(p.scope,name,source,info);err!=nil{return "","",err}
 if err=p.validate();err!=nil{return "","",err}
 success=true;return path,privateDir,nil
}

func readFactPreparedIndex(ctx context.Context,p *factIndexPinnedDirectory,digest string,signatures []string)(*factPreparedIndex,error){
 descriptor,err:=readFactIndexDescriptor(ctx,p,digest);if err!=nil{return nil,err}
 if descriptor.Documents!=len(signatures){return nil,fmt.Errorf("fact index document count changed")}
 path,privateDir,err:=snapshotFactIndex(ctx,p,descriptor);if err!=nil{return nil,err}
 index:=&factPreparedIndex{privateDir:privateDir,generation:digest,reused:true}
 success:=false;defer func(){if !success{_=index.Close()}}()
 index.db,err=sql.Open(sqlitedriver.Name,brainstore.SQLiteReadOnlyDSN(path));if err!=nil{return nil,err};index.db.SetMaxOpenConns(1)
 if _,err=index.db.ExecContext(ctx,`PRAGMA trusted_schema=OFF; PRAGMA query_only=ON;`);err!=nil{return nil,err}
 var source string;var count int
 if err=index.db.QueryRowContext(ctx,`SELECT source,documents FROM fact_index_meta WHERE singleton=1`).Scan(&source,&count);err!=nil{return nil,err}
 if source!=digest||count!=len(signatures){return nil,fmt.Errorf("fact index metadata does not match its source")}
 index.docs,err=readFactIndexDocuments(ctx,index.db,signatures);if err!=nil{return nil,err}
 success=true;return index,nil
}

func readFactIndexDocuments(ctx context.Context,db *sql.DB,signatures []string)([]factIndexDocument,error){
 rows,err:=db.QueryContext(ctx,`SELECT document,signature,length,locus FROM fact_index_documents ORDER BY document`);if err!=nil{return nil,err};defer rows.Close()
 docs:=make([]factIndexDocument,0,len(signatures))
 for rows.Next(){
  if err=ctx.Err();err!=nil{return nil,err}
  var position int;var doc factIndexDocument;var locus string
  if err=rows.Scan(&position,&doc.Signature,&doc.Length,&locus);err!=nil{return nil,err}
  if position!=len(docs)||position>=len(signatures)||doc.Signature!=signatures[position]||doc.Length<0||int64(len(locus))>factIndexMaxBytes{return nil,fmt.Errorf("invalid fact index document")}
  if err=json.Unmarshal([]byte(locus),&doc.Locus);err!=nil{return nil,fmt.Errorf("decode prepared fact locus: %w",err)}
  docs=append(docs,doc)
 }
 if err=rows.Err();err!=nil{return nil,err}
 if len(docs)!=len(signatures){return nil,fmt.Errorf("incomplete fact index documents")}
 return docs,nil
}

func (index *factPreparedIndex) postings(ctx context.Context,term string)([]factIndexPosting,error){
 if err:=ctx.Err();err!=nil{return nil,err}
 rows,err:=index.db.QueryContext(ctx,`SELECT document,frequency FROM fact_index_postings WHERE term=? ORDER BY document`,term);if err!=nil{return nil,err};defer rows.Close()
 out:=make([]factIndexPosting,0);previous:=-1
 for rows.Next(){
  var posting factIndexPosting;if err=rows.Scan(&posting.Document,&posting.Frequency);err!=nil{return nil,err}
  if posting.Document<=previous||posting.Document>=len(index.docs)||posting.Frequency<1||posting.Frequency>index.docs[posting.Document].Length{return nil,fmt.Errorf("invalid fact index posting")}
  previous=posting.Document;out=append(out,posting)
 }
 if err=rows.Err();err!=nil{return nil,err};return out,ctx.Err()
}

func (index *factPreparedIndex) Close()error{
 if index==nil{return nil};var dbErr,removeErr error
 if index.db!=nil{dbErr=index.db.Close();index.db=nil}
 if index.privateDir!=""{removeErr=os.RemoveAll(index.privateDir);index.privateDir=""}
 return errors.Join(dbErr,removeErr)
}

