  if err=ctx.Err();err!=nil{return nil,err}
  var position int;var doc factIndexDocument;var locus string
  if err=rows.Scan(&position,&doc.Signature,&doc.Length,&locus);err!=nil{return nil,err}
  if position!=len(docs)||position>=len(signatures)||doc.Signature!=signatures[position]||doc.Length<0||int64(len(locus))>factIndexMaxBytes{return nil,fmt.Errorf("invalid fact index document")}
  if err=json.Unmarshal([]byte(locus),&doc.Locus);err!=nil{return nil,fmt.Errorf("decode prepared fact locus: %w",err)}
  docs=append(docs,doc)
 }
 if err=rows.Err();err!=nil{return nil,err}
 if len(docs)!=len(signatures){return nil,fmt.Errorf("incomplete fact index documents")}
 return docs,nil
}

func (index *factPreparedIndex) postings(ctx context.Context,term string)([]factIndexPosting,error){
 if err:=ctx.Err();err!=nil{return nil,err}
 rows,err:=index.db.QueryContext(ctx,`SELECT document,frequency FROM fact_index_postings WHERE term=? ORDER BY document`,term);if err!=nil{return nil,err};defer rows.Close()
 out:=make([]factIndexPosting,0);previous:=-1
 for rows.Next(){
  var posting factIndexPosting;if err=rows.Scan(&posting.Document,&posting.Frequency);err!=nil{return nil,err}
  if posting.Document<=previous||posting.Document>=len(index.docs)||posting.Frequency<1||posting.Frequency>index.docs[posting.Document].Length{return nil,fmt.Errorf("invalid fact index posting")}
  previous=posting.Document;out=append(out,posting)
 }
 if err=rows.Err();err!=nil{return nil,err};return out,ctx.Err()
}

func (index *factPreparedIndex) Close()error{
 if index==nil{return nil};var dbErr,removeErr error
 if index.db!=nil{dbErr=index.db.Close();index.db=nil}
 if index.privateDir!=""{removeErr=os.RemoveAll(index.privateDir);index.privateDir=""}
 return errors.Join(dbErr,removeErr)
}

// Missing or damaged derived data is rebuilt under an immediate, cache-only
// lock. The caller decides scan fallback; canonical errors have already been
// observed while obtaining source and are never hidden here.
func openFactPreparedIndex(ctx context.Context,env base.EntireEnv,scope string,source []factRecord)(result *factPreparedIndex,retErr error){
 if ctx==nil{ctx=context.Background()};if err:=ctx.Err();err!=nil{return nil,err}
 digest,signatures,err:=factIndexSourceRevision(ctx,scope,source);if err!=nil{return nil,err}
 pinned,err:=openFactIndexPinnedDirectory(env,scope);if err!=nil{return nil,err};defer pinned.Close()
 index,err:=readFactPreparedIndex(ctx,pinned,digest,signatures);if err==nil{return index,nil}
 if ctx.Err()!=nil{return nil,ctx.Err()};if errors.Is(err,errFactIndexUnsafe){return nil,err}
 lock,err:=brainstore.TryFileLockIn(pinned.scope,factIndexLockName);if err!=nil{return nil,err}
 defer func(){if closeErr:=lock.Close();closeErr!=nil&&retErr==nil{if result!=nil{_=result.Close();result=nil};retErr=closeErr}}()
 if err=pinned.validate();err!=nil{return nil,err}
 index,err=readFactPreparedIndex(ctx,pinned,digest,signatures);if err==nil{return index,nil}
 if ctx.Err()!=nil{return nil,ctx.Err()};if errors.Is(err,errFactIndexUnsafe){return nil,err}
 if err=cleanupFactIndexOrphans(ctx,pinned);err!=nil{return nil,err}
 staging,cleanup,err:=buildFactIndexDatabase(ctx,digest,source,signatures);if err!=nil{return nil,err};defer cleanup()
 if err=publishFactIndexDatabase(ctx,pinned,staging,digest,len(source));err!=nil{return nil,err}
 index,err=readFactPreparedIndex(ctx,pinned,digest,signatures);if err!=nil{return nil,err};index.reused=false
 return index,nil
}

func buildFactIndexDatabase(ctx context.Context,digest string,source []factRecord,signatures []string)(string,func(),error){
 privateDir,err:=os.MkdirTemp("","entire-brain-fact-index-build-");if err!=nil{return "",nil,err}
 cleanup:=func(){_=os.RemoveAll(privateDir)};success:=false;defer func(){if !success{cleanup()}}()
 path:=filepath.Join(privateDir,"index.sqlite")
 db,err:=sql.Open(sqlitedriver.Name,path);if err!=nil{return "",nil,err};defer db.Close();db.SetMaxOpenConns(1)
 pragmas:=fmt.Sprintf(`PRAGMA page_size=4096; PRAGMA max_page_count=%d; PRAGMA journal_mode=DELETE; PRAGMA synchronous=FULL; PRAGMA trusted_schema=OFF;`,factIndexMaxBytes/4096)
 if _,err=db.ExecContext(ctx,pragmas);err!=nil{return "",nil,err}
 tx,err:=db.BeginTx(ctx,nil);if err!=nil{return "",nil,err};defer tx.Rollback()
 if _,err=tx.ExecContext(ctx,`CREATE TABLE fact_index_meta(singleton INTEGER PRIMARY KEY CHECK(singleton=1),source TEXT NOT NULL,documents INTEGER NOT NULL); CREATE TABLE fact_index_documents(document INTEGER PRIMARY KEY,signature TEXT NOT NULL,length INTEGER NOT NULL,locus TEXT NOT NULL); CREATE TABLE fact_index_postings(term TEXT NOT NULL,document INTEGER NOT NULL,frequency INTEGER NOT NULL,PRIMARY KEY(term,document)) WITHOUT ROWID;`);err!=nil{return "",nil,err}
 if err=insertFactIndexDocuments(ctx,tx,source,signatures);err!=nil{return "",nil,err}
 if _,err=tx.ExecContext(ctx,`INSERT INTO fact_index_meta VALUES(1,?,?)`,digest,len(source));err!=nil{return "",nil,err}
 if err=tx.Commit();err!=nil{return "",nil,err}
 if err=db.Close();err!=nil{return "",nil,err}
 f,err:=os.OpenFile(path,os.O_RDWR,0);if err!=nil{return "",nil,err}
 syncErr:=f.Sync();closeErr:=f.Close();if syncErr!=nil{return "",nil,syncErr};if closeErr!=nil{return "",nil,closeErr}
 success=true;return path,cleanup,nil
}

func insertFactIndexDocuments(ctx context.Context,tx *sql.Tx,source []factRecord,signatures []string)error{
 docs,err:=tx.PrepareContext(ctx,`INSERT INTO fact_index_documents VALUES(?,?,?,?)`);if err!=nil{return err};defer docs.Close()
 postings,err:=tx.PrepareContext(ctx,`INSERT INTO fact_index_postings VALUES(?,?,?)`);if err!=nil{return err};defer postings.Close()
 for i:=range source{
  if err=ctx.Err();err!=nil{return err}
  tokens:=factSearchTokens(source[i]);locus,marshalErr:=json.Marshal(base.FactLocusOf(source[i]));if marshalErr!=nil{return marshalErr}
  if _,err=docs.ExecContext(ctx,i,signatures[i],len(tokens),string(locus));err!=nil{return err}
  counts:=make(map[string]int,len(tokens));for _,token:=range tokens{counts[token]++}
  for token,n:=range counts{if _,err=postings.ExecContext(ctx,token,i,n);err!=nil{return err}}
 }
 return nil
}

func factIndexRandomName(suffix string)(string,error){
 var data [16]byte;if _,err:=rand.Read(data[:]);err!=nil{return "",err}
 return factIndexPublishPrefix+hex.EncodeToString(data[:])+suffix,nil
}

func createFactIndexPublicationLeaf(root *os.Root,suffix string)(*os.File,string,error){
 name,err:=factIndexRandomName(suffix);if err!=nil{return nil,"",err}
 f,err:=root.OpenFile(name,os.O_CREATE|os.O_EXCL|os.O_WRONLY|base.FileLockOpenFlags(),0600);if err!=nil{return nil,"",err}
 return f,name,nil
}

func publishFactIndexDatabase(ctx context.Context,p *factIndexPinnedDirectory,staging,digest string,count int)error{
 source,err:=os.Open(staging);if err!=nil{return err};defer source.Close()
 target,tempName,err:=createFactIndexPublicationLeaf(p.scope,".sqlite");if err!=nil{return err}
 defer func(){_=target.Close();_=p.scope.Remove(tempName)}()
 h:=sha256.New();n,err:=io.CopyBuffer(io.MultiWriter(target,h),io.LimitReader(&factIndexContextReader{ctx:ctx,reader:source},factIndexMaxBytes+1),make([]byte,64<<10))
 if err!=nil{return err};if n<1||n>factIndexMaxBytes{return errFactIndexBudget}
 if err=target.Sync();err!=nil{return err};if err=target.Close();err!=nil{return err}
 if err=p.validate();err!=nil{return err}
 // Verify an old committed generation before pruning to one. A failed new
 // publication then still retains a complete, byte-verified old generation.
 if err=retainFactIndexGenerations(ctx,p,digest,1);err!=nil{return err}
 if err=replaceFactIndexLeaf(p,tempName,digest+".sqlite");err!=nil{return err}
 if err=brainstore.SyncPinnedDirectory(p.scope);err!=nil{return err}
 descriptor:=factIndexDescriptor{Revision:currentFactIndexRevision(),Source:digest,Documents:count,Size:n,SHA256:hex.EncodeToString(h.Sum(nil)),CreatedAt:time.Now().UTC()}
 data,err:=json.Marshal(descriptor);if err!=nil{return err}
 marker,markerName,err:=createFactIndexPublicationLeaf(p.scope,".json");if err!=nil{return err}
 defer func(){_=marker.Close();_=p.scope.Remove(markerName)}()
 if _,err=marker.Write(append(data,'\n'));err!=nil{return err};if err=marker.Sync();err!=nil{return err};if err=marker.Close();err!=nil{return err}
 if err=ctx.Err();err!=nil{return err}
 // The descriptor is the commit record and is always published last.
 if err=replaceFactIndexLeaf(p,markerName,digest+".json");err!=nil{return err}
 if err=brainstore.SyncPinnedDirectory(p.scope);err!=nil{return err}
 return p.validate()
}

func replaceFactIndexLeaf(p *factIndexPinnedDirectory,from,to string)error{
 if err:=p.validate();err!=nil{return err}
 info,err:=p.scope.Lstat(to)
 if err!=nil&&!os.IsNotExist(err){return err}
 if err==nil&&(info.Mode()&os.ModeSymlink!=0||!info.Mode().IsRegular()){return fmt.Errorf("%w: publication target is not a regular file",errFactIndexUnsafe)}
 return p.scope.Rename(from,to)
}

func factIndexDirectoryEntries(p *factIndexPinnedDirectory)([]os.DirEntry,error){
 f,err:=p.scope.Open(".");if err!=nil{return nil,err};defer f.Close()
 entries,err:=f.ReadDir(factIndexMaxDirectoryEntries+1)
 if err!=nil&&!errors.Is(err,io.EOF){return nil,err}
 if len(entries)>factIndexMaxDirectoryEntries{return nil,errFactIndexBudget}
 return entries,p.validate()
}

func factIndexGenerationName(name,suffix string)(string,bool){
 if !strings.HasSuffix(name,suffix){return "",false}
 digest:=strings.TrimSuffix(name,suffix);return digest,factIndexHexDigest(digest)
}

func removeFactIndexLeaf(p *factIndexPinnedDirectory,name string)error{
 info,err:=p.scope.Lstat(name);if os.IsNotExist(err){return nil};if err!=nil{return err}
 if info.Mode()&os.ModeSymlink!=0||!info.Mode().IsRegular(){return fmt.Errorf("%w: cleanup target is not a regular file",errFactIndexUnsafe)}
 if err=p.validate();err!=nil{return err};return p.scope.Remove(name)
}

func cleanupFactIndexOrphans(ctx context.Context,p *factIndexPinnedDirectory)error{
 entries,err:=factIndexDirectoryEntries(p);if err!=nil{return err}
 for _,entry:=range entries{
  if err=ctx.Err();err!=nil{return err}
  name:=entry.Name()
  if strings.HasPrefix(name,factIndexPublishPrefix){if err=removeFactIndexLeaf(p,name);err!=nil{return err};continue}
  digest,ok:=factIndexGenerationName(name,".sqlite");if !ok{continue}
  _,err=p.scope.Lstat(digest+".json")
  if os.IsNotExist(err){if err=removeFactIndexLeaf(p,name);err!=nil{return err}}else if err!=nil{return err}
 }
 return nil
}

func verifyFactIndexGeneration(ctx context.Context,p *factIndexPinnedDirectory,descriptor factIndexDescriptor)error{
 name:=descriptor.Source+".sqlite";f,info,err:=factIndexOpenLeaf(p.scope,name,factIndexMaxBytes);if err!=nil{return err};defer f.Close()
 h:=sha256.New();n,err:=io.CopyBuffer(h,io.LimitReader(&factIndexContextReader{ctx:ctx,reader:f},factIndexMaxBytes+1),make([]byte,64<<10));if err!=nil{return err}
 if n!=descriptor.Size||hex.EncodeToString(h.Sum(nil))!=descriptor.SHA256{return fmt.Errorf("fact index retention candidate failed its digest")}
 return factIndexLeafUnchanged(p.scope,name,f,info)
}

func retainFactIndexGenerations(ctx context.Context,p *factIndexPinnedDirectory,replacing string,keep int)error{
 entries,err:=factIndexDirectoryEntries(p);if err!=nil{return err}
 type candidate struct{digest string;descriptor factIndexDescriptor;valid bool}
 generations:=make([]candidate,0,2)
 for _,entry:=range entries{
  digest,ok:=factIndexGenerationName(entry.Name(),".json");if !ok||digest==replacing{continue}
  descriptor,readErr:=readFactIndexDescriptor(ctx,p,digest)
  if errors.Is(readErr,errFactIndexUnsafe){return readErr}
  generations=append(generations,candidate{digest:digest,descriptor:descriptor,valid:readErr==nil})
 }
 if len(generations)>4{return errFactIndexBudget}
 sort.Slice(generations,func(i,j int)bool{return generations[i].descriptor.CreatedAt.After(generations[j].descriptor.CreatedAt)})
 retained:=0
 for _,generation:=range generations{
  if err=ctx.Err();err!=nil{return err}
  if generation.valid&&retained<keep{
   if verifyErr:=verifyFactIndexGeneration(ctx,p,generation.descriptor);verifyErr==nil{retained++;continue}else if errors.Is(verifyErr,errFactIndexUnsafe){return verifyErr}
  }
  // Removing the descriptor first uncommits the database before unlink.
  if err=removeFactIndexLeaf(p,generation.digest+".json");err!=nil{return err}
  if err=removeFactIndexLeaf(p,generation.digest+".sqlite");err!=nil{return err}
 }
 return brainstore.SyncPinnedDirectory(p.scope)
}
