func factIndexOpenDirectoryPath(path string)(*os.Root,os.FileInfo,error){
 info,err:=os.Lstat(path)
 if os.IsNotExist(err){
  parentPath:=filepath.Dir(path)
  if parentPath==path{return nil,nil,err}
  parent,_,openErr:=factIndexOpenDirectoryPath(parentPath);if openErr!=nil{return nil,nil,openErr}
  defer parent.Close()
