 if info.Mode()&os.ModeSymlink!=0||!info.Mode().IsRegular(){return nil,nil,fmt.Errorf("%w: cache leaf is not a regular file",errFactIndexUnsafe)}
 if info.Size()<1||info.Size()>max{return nil,nil,errFactIndexBudget}
 f,err:=root.OpenFile(name,os.O_RDONLY|base.FileLockOpenFlags()|base.MemoryStateReadOpenFlags(),0);if err!=nil{return nil,nil,err}
