}

func readFactIndexDescriptor(ctx context.Context,p *factIndexPinnedDirectory,digest string)(factIndexDescriptor,error){
 var descriptor factIndexDescriptor
 name:=digest+".json";f,info,err:=factIndexOpenLeaf(p.scope,name,factIndexDescriptorMaxBytes);if err!=nil{return descriptor,err};defer f.Close()
 data,err:=io.ReadAll(io.LimitReader(&factIndexContextReader{ctx:ctx,reader:f},factIndexDescriptorMaxBytes+1));if err!=nil{return descriptor,err}
 if int64(len(data))>factIndexDescriptorMaxBytes{return descriptor,errFactIndexBudget}
 if err=factIndexLeafUnchanged(p.scope,name,f,info);err!=nil{return descriptor,err}
 decoder:=json.NewDecoder(bytes.NewReader(data));decoder.DisallowUnknownFields()
 if err=decoder.Decode(&descriptor);err!=nil{return descriptor,fmt.Errorf("decode fact index descriptor: %w",err)}
 var extra any;if err=decoder.Decode(&extra);!errors.Is(err,io.EOF){return descriptor,fmt.Errorf("invalid trailing fact index descriptor data")}
 if descriptor.Revision!=currentFactIndexRevision()||descriptor.Source!=digest||!factIndexHexDigest(descriptor.SHA256)||descriptor.Size<1||descriptor.Size>factIndexMaxBytes||descriptor.Documents<0||descriptor.Documents>factIndexMaxDocuments{return descriptor,fmt.Errorf("invalid fact index descriptor")}
 return descriptor,p.validate()
}

