}

// Only this descriptor-bound private snapshot is ever passed to SQLite. The
// byte digest covers postings and computed loci, not merely database metadata.
func snapshotFactIndex(ctx context.Context,p *factIndexPinnedDirectory,descriptor factIndexDescriptor)(string,string,error){
 name:=descriptor.Source+".sqlite";source,info,err:=factIndexOpenLeaf(p.scope,name,factIndexMaxBytes);if err!=nil{return "","",err};defer source.Close()
 if info.Size()!=descriptor.Size{return "","",fmt.Errorf("fact index database size changed")}
