func BenchmarkFactIndexPhases(b *testing.B) {
	type corpus struct {
		name  string
		count int
		store string
	}
	corpora := []corpus{{name: "synthetic-44", count: 44}, {name: "synthetic-1000", count: 1000},
		{name: "synthetic-10000", count: 10000}, {name: "synthetic-50000", count: 50000}}
	if store := os.Getenv("ENTIRE_FACT_INDEX_BENCH_PUBLIC_STORE"); store != "" {
		if !filepath.IsAbs(store) || filepath.Base(store) != "store.json" {
			b.Fatal("ENTIRE_FACT_INDEX_BENCH_PUBLIC_STORE must name an absolute facts/store.json")
		}
		corpora = append(corpora, corpus{name: "public-import", store: store})
	}
	for _, corpus := range corpora {
		b.Run(corpus.name, func(b *testing.B) {
			records := factProcessSynthetic(corpus.count)
			if corpus.store != "" {
				var err error
				records, err = factstore.Load(filepath.Dir(filepath.Dir(corpus.store)))
				if err != nil || len(records) == 0 {
					b.Fatalf("load public corpus: count=%d error=%v", len(records), err)
				}
			}
			root := b.TempDir()
			brainDir := filepath.Join(root, "data", "repos", "local", "fixture")
			if err := factstore.Write(brainDir, records); err != nil {
				b.Fatal(err)
			}
			env := base.EntireEnv{PluginConfigDir: filepath.Join(root, "config"), PluginDataDir: filepath.Join(root, "data"),
				PluginStateDir: filepath.Join(root, "state"), PluginCacheDir: filepath.Join(root, "cache")}
			ctx := context.Background()
			now := time.Date(2026, 11, 16, 0, 0, 0, 0, time.UTC)
			b.Run("load", func(b *testing.B) {
				b.ReportAllocs()
				for b.Loop() {
					loaded, err := factstore.Load(brainDir)
					if err != nil || len(loaded) != len(records) {
						b.Fatalf("load: count=%d error=%v", len(loaded), err)
					}
				}
			})
			// Signature hashing is a real per-request cost, separate from loading.
			b.Run("record_signatures", func(b *testing.B) {
				b.ReportAllocs()
				for b.Loop() {
					for _, record := range records {
						if _, err := factIndexRecordSignature(record); err != nil {
							b.Fatal(err)
						}
					}
				}
			})
			// Prepare a disposable warm generation once, outside timed loops.
			index, err := openFactPreparedIndex(ctx, env, brainDir, records)
			if err != nil {
				b.Fatal(err)
			}
			if err := index.Close(); err != nil {
				b.Fatal(err)
			}
			b.Run("index_open_revision_documents", func(b *testing.B) {
				b.ReportAllocs()
				for b.Loop() {
					index, err := openFactPreparedIndex(ctx, env, brainDir, records)
					if err != nil {
						b.Fatal(err)
					}
					if !index.reused {
						_ = index.Close()
						b.Fatal("expected a warm prepared index")
					}
					if err := index.Close(); err != nil {
						b.Fatal(err)
					}
				}
			})
			queries := []string{"checkpoint retry", "4321", "absentzzzz", ""}
			if corpus.store != "" {
				queries = []string{"When did Caroline go to the LGBTQ support group?", "When did John have a party with veterans?", "absentzzzz", ""}
			}
			for qi, query := range queries {
				b.Run(fmt.Sprintf("query-%d", qi), func(b *testing.B) {
					want := rankFactsAt(records, query, 10, false, now)
					got, err := rankFactsIndexedAt(ctx, env, brainDir, records, records, query, 10, false, now)
					wantJSON, _ := json.Marshal(want)
					gotJSON, _ := json.Marshal(got)
					if err != nil || !bytes.Equal(wantJSON, gotJSON) {
						b.Fatalf("ranking mismatch before timing: %v", err)
					}
					b.Run("scan_rank", func(b *testing.B) {
						b.ReportAllocs()
						for b.Loop() {
							_ = rankFactsAt(records, query, 10, false, now)
						}
					})
					b.Run("indexed_rank", func(b *testing.B) {
						b.ReportAllocs()
						for b.Loop() {
							if _, err := rankFactsIndexedAt(ctx, env, brainDir, records, records, query, 10, false, now); err != nil {
								b.Fatal(err)
							}
						}
					})
					if len(factQueryTerms(query)) == 0 {
						return
					}
					b.Run("postings", func(b *testing.B) {
						index, err := openFactPreparedIndex(ctx, env, brainDir, records)
						if err != nil {
							b.Fatal(err)
						}
						defer index.Close()
						terms := factQueryTerms(query)
						b.ReportAllocs()
						b.ResetTimer()
						for b.Loop() {
							for _, term := range terms {
								if _, err := index.postings(ctx, term); err != nil {
									b.Fatal(err)
								}
							}
						}
					})
				})
			}
		})
	}
}
package brainstore

import (
	"fmt"
	"os"
	"path/filepath"
	"time"

	"github.com/entireio/entire-brain/internal/cli/internal/base"
)

// TryFileLockIn immediately acquires an optional-cache lock beneath an already
// pinned directory. It shares the process and OS lock implementations with
// AcquireFileLock, but performs no absolute-path I/O or diagnostic sidecar write.
// A busy lock returns ErrFileLockTimeout, allowing the caller to scan instead.
func TryFileLockIn(root *os.Root, name string) (*FileLock, error) {
	if root == nil || name == "." || name == ".." || name == "" || name != filepath.Base(name) {
		return nil, fmt.Errorf("cache lock requires a pinned root and a leaf name")
	}
	parent, err := root.Stat(".")
	if err != nil {
		return nil, fmt.Errorf("inspect cache lock root: %w", err)
	}
	processLock, ok := acquireProcessFileLock(parent, name, time.Now(), 0)
	if !ok {
		return nil, fmt.Errorf("cache lock busy: %w", ErrFileLockTimeout)
	}
	owned := true
	defer func() {
		if owned {
			processLock.release()
		}
	}()
	if info, statErr := root.Lstat(name); statErr == nil {
		if !info.Mode().IsRegular() {
			return nil, fmt.Errorf("cache lock is not a regular file")
		}
	} else if !os.IsNotExist(statErr) {
		return nil, fmt.Errorf("inspect cache lock: %w", statErr)
	}
	f, err := root.OpenFile(name, os.O_CREATE|os.O_RDWR|base.FileLockOpenFlags(), 0o600)
	if err != nil {
		return nil, fmt.Errorf("open rooted cache lock: %w", err)
	}
	defer func() {
		if owned {
			_ = f.Close()
		}
	}()
	opened, err := f.Stat()
	if err != nil {
		return nil, fmt.Errorf("inspect opened cache lock: %w", err)
	}
	current, err := root.Lstat(name)
	if err != nil || !opened.Mode().IsRegular() || !current.Mode().IsRegular() || !os.SameFile(opened, current) {
		return nil, fmt.Errorf("cache lock changed while opening")
	}
	if err := base.RejectOpenFileHardlink(name, f, opened, "cache lock"); err != nil {
		return nil, err
	}
	if err := tryLockFile(f); err != nil {
		if isLockBusy(err) {
			return nil, fmt.Errorf("cache lock busy: %w", ErrFileLockTimeout)
		}
		return nil, fmt.Errorf("lock rooted cache file: %w", err)
	}
	owned = false
	return &FileLock{file: f, processLock: processLock}, nil
}

