	if !strings.HasPrefix(name, factIndexPublishPrefix) {
		return false
	}
	body := strings.TrimPrefix(name, factIndexPublishPrefix)
	if strings.HasSuffix(body, ".sqlite") {
		body = strings.TrimSuffix(body, ".sqlite")
	} else if strings.HasSuffix(body, ".json") {
		body = strings.TrimSuffix(body, ".json")
	} else {
		return false
	}
	data, err := hex.DecodeString(body)
	return err == nil && len(data) == 16 && strings.ToLower(body) == body
}

