				return err
			}
		} else if err != nil {
			return err
		}
	}
	return nil
}

func verifyFactIndexGeneration(ctx context.Context, p *factIndexPinnedDirectory, descriptor factIndexDescriptor) error {
	name := descriptor.Source + ".sqlite"
	f, info, err := factIndexOpenLeaf(p.scope, name, factIndexMaxBytes)
	if err != nil {
		return err
	}
	defer f.Close()
	h := sha256.New()
	n, err := io.CopyBuffer(h, io.LimitReader(&factIndexContextReader{ctx: ctx, reader: f}, factIndexMaxBytes+1), make([]byte, 64<<10))
	if err != nil {
		return err
	}
	if n != descriptor.Size || hex.EncodeToString(h.Sum(nil)) != descriptor.SHA256 {
		return fmt.Errorf("fact index retention candidate failed its digest")
	}
	return factIndexLeafUnchanged(p.scope, name, f, info)
}

func retainFactIndexGenerations(ctx context.Context, p *factIndexPinnedDirectory, replacing string, keep int) error {
	entries, err := factIndexDirectoryEntries(p)
	if err != nil {
		return err
	}
	type candidate struct {
		digest     string
		descriptor factIndexDescriptor
		valid      bool
	}
	generations := make([]candidate, 0, 2)
	for _, entry := range entries {
		digest, ok := factIndexGenerationName(entry.Name(), ".json")
		if !ok || digest == replacing {
			continue
		}
		descriptor, readErr := readFactIndexDescriptor(ctx, p, digest)
		if errors.Is(readErr, errFactIndexUnsafe) {
			return readErr
		}
		generations = append(generations, candidate{digest: digest, descriptor: descriptor, valid: readErr == nil})
	}
	if len(generations) > 4 {
		return errFactIndexBudget
	}
	sort.Slice(generations, func(i, j int) bool {
		return generations[i].descriptor.CreatedAt.After(generations[j].descriptor.CreatedAt)
	})
	retained := 0
	for _, generation := range generations {
		if err = ctx.Err(); err != nil {
			return err
		}
		if generation.valid && retained < keep {
			if verifyErr := verifyFactIndexGeneration(ctx, p, generation.descriptor); verifyErr == nil {
				retained++
				continue
			} else if errors.Is(verifyErr, errFactIndexUnsafe) {
				return verifyErr
			}
		}
		// Removing the descriptor first uncommits the database before unlink.
		if err = removeFactIndexLeaf(p, generation.digest+".json"); err != nil {
			return err
		}
		if err = removeFactIndexLeaf(p, generation.digest+".sqlite"); err != nil {
			return err
		}
	}
	return brainstore.SyncPinnedDirectory(p.scope)
}

