		return nil, err
	}
	return docs, ctx.Err()
}

// Decode one metadata document at a time and stop before allocating an
// unexpected extra document. The source count is known from fresh records.
func decodeFactIndexDocuments(ctx context.Context, data []byte, signatures []string) ([]factIndexDocument, error) {
	if int64(len(data)) > factIndexMaxBytes {
		return nil, errFactIndexBudget
	}
	decoder := json.NewDecoder(&factIndexContextReader{ctx: ctx, reader: bytes.NewReader(data)})
	decoder.DisallowUnknownFields()
	token, err := decoder.Token()
	if err != nil {
		return nil, err
	}
	if token != json.Delim('[') {
		return nil, fmt.Errorf("invalid fact index document vector")
	}
	docs := make([]factIndexDocument, 0, len(signatures))
	for decoder.More() {
		if err = ctx.Err(); err != nil {
			return nil, err
		}
		if len(docs) >= len(signatures) {
			return nil, fmt.Errorf("excess fact index documents")
		}
		var doc factIndexDocument
		if err = decoder.Decode(&doc); err != nil {
			return nil, fmt.Errorf("decode prepared fact document: %w", err)
		}
		if doc.Length < 0 {
			return nil, fmt.Errorf("invalid fact index document")
		}
		doc.Signature = signatures[len(docs)]
		docs = append(docs, doc)
	}
	token, err = decoder.Token()
	if err != nil {
		return nil, err
	}
	if token != json.Delim(']') {
		return nil, fmt.Errorf("invalid fact index document vector end")
	}
	var extra any
	if err = decoder.Decode(&extra); !errors.Is(err, io.EOF) {
		return nil, fmt.Errorf("invalid trailing fact index document data")
	}
	if len(docs) != len(signatures) {
		return nil, fmt.Errorf("incomplete fact index documents")
	}
	return docs, ctx.Err()
}

func (index *factPreparedIndex) postings(ctx context.Context, term string) ([]factIndexPosting, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	rows, err := index.db.QueryContext(ctx, `SELECT document,frequency FROM fact_index_postings WHERE term=? ORDER BY document`, term)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := make([]factIndexPosting, 0)
	previous := -1
	for rows.Next() {
		var posting factIndexPosting
		if err = rows.Scan(&posting.Document, &posting.Frequency); err != nil {
			return nil, err
		}
		if posting.Document <= previous || posting.Document >= len(index.docs) || posting.Frequency < 1 || posting.Frequency > index.docs[posting.Document].Length {
			return nil, fmt.Errorf("invalid fact index posting")
		}
		previous = posting.Document
		out = append(out, posting)
	}
	if err = rows.Err(); err != nil {
		return nil, err
	}
	return out, ctx.Err()
}

func (index *factPreparedIndex) Close() error {
	if index == nil {
		return nil
	}
	var dbErr, removeErr error
	if index.db != nil {
		dbErr = index.db.Close()
		index.db = nil
	}
	if index.privateDir != "" {
		removeErr = os.RemoveAll(index.privateDir)
		index.privateDir = ""
	}
	return errors.Join(dbErr, removeErr)
}

