	}
	data, err := hex.DecodeString(body)
	return err == nil && len(data) == 16 && strings.ToLower(body) == body
}

func cleanupFactIndexOrphans(ctx context.Context, p *factIndexPinnedDirectory) error {
	entries, err := factIndexDirectoryEntries(p)
	if err != nil {
