// cause an older, still-committed blob to be removed.
func cleanupFactIndexOrphans(ctx context.Context, p *factIndexPinnedDirectory) error {
	entries, err := factIndexDirectoryEntries(p)
	if err != nil {
		return err
	}
	type marker struct {
		descriptor factIndexDescriptor
		usable bool
	}
	markers := make(map[string]marker)
	remove := make([]string, 0)
	for _, entry := range entries {
		if err = ctx.Err(); err != nil {
			return err
		}
		name := entry.Name()
		if factIndexPublicationName(name) {
			remove = append(remove, name)
			continue
		}
		source, ok := factIndexDatabaseSource(name)
		if !ok {
			continue
		}
		m, seen := markers[source]
		if !seen {
			descriptor, readErr := readFactIndexDescriptor(ctx, p, source)
			if readErr != nil && !factIndexKnownUnusable(readErr) {
				return readErr
			}
			m = marker{descriptor: descriptor, usable: readErr == nil}
			markers[source] = m
		}
		if !m.usable || name != factIndexDatabaseName(m.descriptor) {
			remove = append(remove, name)
		}
	}
	if err = preflightFactIndexRemovals(p, remove); err != nil {
		return err
	}
	for _, name := range remove {
		if err = ctx.Err(); err != nil {
			return err
		}
		if err = removeFactIndexLeaf(p, name); err != nil {
			return err
		}
	}
	if len(remove) != 0 {
		return brainstore.SyncPinnedDirectory(p.scope)
	}
	return nil
}

func verifyFactIndexGeneration(ctx context.Context, p *factIndexPinnedDirectory, descriptor factIndexDescriptor) error {
	name := factIndexDatabaseName(descriptor)
	f, info, err := factIndexOpenLeaf(p.scope, name, factIndexMaxBytes)
	if err != nil {
		return err
	}
	defer f.Close()
	h := sha256.New()
	n, err := io.CopyBuffer(h, io.LimitReader(&factIndexContextReader{ctx: ctx, reader: f}, factIndexMaxBytes+1), make([]byte, 64<<10))
	if err != nil {
		return err
	}
	if n != descriptor.Size || hex.EncodeToString(h.Sum(nil)) != descriptor.SHA256 {
		return fmt.Errorf("%w: retention candidate failed its digest", errFactIndexCorrupt)
	}
	return factIndexLeafUnchanged(p.scope, name, f, info)
}

func publishFactIndexBlob(ctx context.Context, p *factIndexPinnedDirectory, from string, descriptor factIndexDescriptor) error {
	// Reuse an already valid content-addressed blob without replacing its inode.
	// A damaged regular blob may be repaired; unsafe aliases and uncertain I/O
	// failures never justify replacing anything.
	if err := verifyFactIndexGeneration(ctx, p, descriptor); err == nil {
		return removeFactIndexLeaf(p, from)
	} else if !factIndexKnownUnusable(err) {
		return err
	}
	return replaceFactIndexLeaf(p, from, factIndexDatabaseName(descriptor))
}

func preflightFactIndexRemovals(p *factIndexPinnedDirectory, names []string) error {
	for _, name := range names {
		f, info, err := factIndexOpenRegularLeaf(p.scope, name)
		if os.IsNotExist(err) {
			continue
		}
		if err != nil {
			return err
		}
		readErr := factIndexLeafUnchanged(p.scope, name, f, info)
		closeErr := f.Close()
		if err = errors.Join(readErr, closeErr); err != nil {
			return err
		}
	}
	return p.validate()
}

func retainFactIndexGenerations(ctx context.Context, p *factIndexPinnedDirectory, replacing string, keep int) error {
	entries, err := factIndexDirectoryEntries(p)
	if err != nil {
		return err
	}
	type candidate struct {
		digest     string
		descriptor factIndexDescriptor
		valid      bool
	}
	generations := make([]candidate, 0, 2)
	for _, entry := range entries {
		digest, ok := factIndexGenerationName(entry.Name(), ".json")
		if !ok || digest == replacing {
			continue
		}
		descriptor, readErr := readFactIndexDescriptor(ctx, p, digest)
		if readErr != nil && !factIndexKnownUnusable(readErr) {
			return readErr
		}
		generations = append(generations, candidate{digest: digest, descriptor: descriptor, valid: readErr == nil})
	}
	if len(generations) > 4 {
		return errFactIndexBudget
	}
	sort.Slice(generations, func(i, j int) bool {
		return generations[i].descriptor.CreatedAt.After(generations[j].descriptor.CreatedAt)
	})
	retained := 0
	remove := make([]string, 0)
	for _, generation := range generations {
		if err = ctx.Err(); err != nil {
			return err
		}
		if generation.valid && retained < keep {
			if verifyErr := verifyFactIndexGeneration(ctx, p, generation.descriptor); verifyErr == nil {
				retained++
				continue
			} else if !factIndexKnownUnusable(verifyErr) {
				return verifyErr
			}
		}
