		// The retained generation is fully verified before any unlink occurs.
		remove = append(remove, generation.digest+".json")
		for _, entry := range entries {
			if source, ok := factIndexDatabaseSource(entry.Name()); ok && source == generation.digest {
				remove = append(remove, entry.Name())
			}
		}
	}
	if err = preflightFactIndexRemovals(p, remove); err != nil {
		return err
	}
	for _, name := range remove {
		if err = ctx.Err(); err != nil {
			return err
		}
		if err = removeFactIndexLeaf(p, name); err != nil {
			return err
		}
	}
	return brainstore.SyncPinnedDirectory(p.scope)
}
